      "code": "rows_data = cells('W0::Knot measurements', 'B702:C706')
pts = sorted([(float(row[0]), float(row[1])) for row in rows_data])

# Integrate piecewise linear from X=2 to X=18
x_start = 2.0
x_end = 18.0

# Helper to get Y at any X via linear interpolation
def get_y(x):
    for i in range(len(pts) - 1):
        x0, y0 = pts[i]
        x1, y1 = pts[i+1]
        if x0 <= x <= x1:
            if x0 == x1:
                return y0
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    return None

# We will use trapezoidal integration over segments between x_start and x_end
active_pts = [x_start] + [p[0] for p in pts if x_start < p[0] < x_end] + [x_end]
active_pts = sorted(list(set(active_pts)))

total_area = 0.0
for i in range(len(active_pts) - 1):
	pa = active_pts[i]
	pb = active_pts[i+1]
	ya = get_y(pa)
	yb = get_y(pb)
	total_area += (ya + yb) * (pb - pa) / 2.0

result = round(total_area, 2)",
